-- ------------------------------------------------------------
-- 200640: now a debuff on the charged enemy.
-- UPDATE, not a re-INSERT: 200640 is a custom spell and does not exist in the
-- base Spell.dbc, so gen_sql.py cannot regenerate its row -- and a hand-built
-- full-row INSERT would quietly revert the duration and aura type that
-- woa_2026_08_09_05.sql set.
-- ------------------------------------------------------------
UPDATE `alonecraft_spell_dbc`
   SET `EffectImplicitTargetA1` = 6,
       `SpellName0`             = 'Staggered',
       `SpellDescription0`      = 'Damage done reduced by $s1%.',
       `SpellToolTip0`          = 'Damage done reduced by $s1%.'
 WHERE `ID` = 200640;
